import numpy as np
from pathlib import Path

def _parse_counts(line): return [int(x) for x in line.split()]
def _parse_elems(line):  return line.split()

def read_poscar_keep9(path):
    """Return (header9, coords[N,3], flags[N][3], elems, counts). Assumes Selective+Direct."""
    lines = Path(path).read_text().splitlines()
    if len(lines) < 10:
        raise ValueError("POSCAR too short.")
    header9 = "\n".join(lines[:9]) + "\n"

    elems  = _parse_elems(lines[5])
    counts = _parse_counts(lines[6])
    natoms = sum(counts)

    if "selective" not in lines[7].lower():
        raise ValueError("Expected 'Selective dynamics' on line 8.")
    if not lines[8].strip().lower().startswith("direct"):
        raise ValueError("This script expects 'Direct' coordinates on line 9.")

    coords, flags = [], []
    start = 9
    for i in range(natoms):
        parts = lines[start + i].split()
        if len(parts) < 6:
            raise ValueError(f"Atom line {i+1} missing selective flags.")
        coords.append([float(parts[0]), float(parts[1]), float(parts[2])])
        flags.append(parts[3:6])

    return header9, np.asarray(coords, float), flags, elems, counts

def _scale_L_cnorm_from_header9(header9):
    """Extract scale, lattice (3x3), and |c|."""
    lines = header9.strip("\n").splitlines()
    scale = float(lines[1].split()[0])
    lattice = np.array([[float(x) for x in lines[i].split()] for i in range(2,5)])
    c_norm = np.linalg.norm(lattice[2])
    return scale, lattice, c_norm

def write_poscar_from9(path, header9, coords, flags):
    """Write POSCAR reusing exact header9 and flags."""
    if len(coords) != len(flags):
        raise ValueError("coords and flags length mismatch.")
    with open(path, "w") as f:
        f.write(header9)
        for i in range(len(coords)):
            x, y, z = coords[i]
            fx, fy, fz = flags[i]
            f.write(f" {x: .10f} {y: .10f} {z: .10f}  {fx}  {fy}  {fz}\n")

def frac_min_image_delta(f0, f1):
    """Minimum-image delta in fractional coords, component-wise in (-0.5, 0.5]."""
    d = f1 - f0
    return d - np.round(d)

def make_interpolated_images(c0, c1, n_images):
    """Return list of (coords, alpha) for internal images (excluding endpoints)."""
    if n_images <= 0:
        return []
    df = frac_min_image_delta(c0, c1)
    imgs = []
    for k in range(1, n_images + 1):
        alpha = k / (n_images + 1)  # 0.25, 0.50, 0.75 for n_images=3
        imgs.append((c0 + alpha * df, alpha))
    return imgs

def make_extrapolated_images(c0, c1, n_before=0, n_after=0):
    """
    Return:
      befores: list of (coords, alpha) with coords at c0 - alpha*df, alpha in (0,1) e.g. 0.50
      afters : list of (coords, alpha) with coords at c1 + alpha*df, alpha in (0,1) e.g. 0.50
    """
    df = frac_min_image_delta(c0, c1)
    befores, afters = [], []
    for k in range(1, n_before + 1):
        alpha = k / (n_before + 1)
        befores.append((c0 - alpha * df, alpha))
    for k in range(1, n_after + 1):
        alpha = k / (n_after + 1)
        afters.append((c1 + alpha * df, alpha))
    return befores, afters

def _species_ranges(elems, counts):
    """Dict {elem: (start,end)} from POSCAR ordering."""
    ranges, idx = {}, 0
    for el, n in zip(elems, counts):
        ranges[el] = (idx, idx + n)
        idx += n
    return ranges

def au_top_tio2_distance_A(header9, coords, elems, counts):
    """
    Δz (Å) = <z_Au4> - <z_top(Ti8 + O16)>, using fractional z and converting by scale*|c|.
    Positive if Au sits above the top TiO2 layer along +c.
    """
    scale, lattice, c_norm = _scale_L_cnorm_from_header9(header9)
    ranges = _species_ranges(elems, counts)
    for need in ("Ti", "O", "Au"):
        if need not in ranges:
            raise ValueError(f"Element '{need}' not found in POSCAR species line.")

    ti_s, ti_e = ranges["Ti"]
    o_s,  o_e  = ranges["O"]
    au_s, au_e = ranges["Au"]

    ti, o, au = coords[ti_s:ti_e], coords[o_s:o_e], coords[au_s:au_e]
    if (ti.shape[0] < 8) or (o.shape[0] < 16) or (au.shape[0] < 4):
        raise ValueError("Need at least Ti≥8, O≥16, Au≥4 for top-layer averaging.")

    ti_top = ti[np.argsort(ti[:,2])[-8:]]
    o_top  =  o[np.argsort(o[:,2])[-16:]]
    z_tio2_top_avg = np.mean(np.concatenate([ti_top[:,2], o_top[:,2]]))
    z_au_avg       = np.mean(au[:,2])

    dz_frac = z_au_avg - z_tio2_top_avg
    return dz_frac * c_norm * scale

def r3(x):  # round to 0.001 Å
    return f"{round(float(x), 3):.3f}"

def main(file1, file2, n_images=3, n_before=1, n_after=1):
    # Read endpoints
    header1, c0, flags0, elems1, counts1 = read_poscar_keep9(file1)
    header2, c1, _     , elems2, counts2 = read_poscar_keep9(file2)
    if elems1 != elems2 or counts1 != counts2:
        raise ValueError("Elements or counts differ between file1 and file2.")
    if c0.shape != c1.shape:
        raise ValueError("Atom counts differ between the two POSCARs.")

    # Endpoint distances with their own headers
    d1 = au_top_tio2_distance_A(header1, c0, elems1, counts1)
    d2 = au_top_tio2_distance_A(header2, c1, elems2, counts2)

    # Generate images
    mids = make_interpolated_images(c0, c1, n_images)             # list of (coords, alpha)
    befores, afters = make_extrapolated_images(c0, c1, n_before, n_after)

    # Log header
    log = []
    log.append(f"file1: {file1}    dz_A = {r3(d1)}\n")
    log.append(f"file2: {file2}    dz_A = {r3(d2)}\n")

    # Write befores: ei.<alpha>.vasp
    for coords, alpha in befores:
        fname = f"ei.{alpha:.2f}.vasp"
        write_poscar_from9(fname, header1, coords, flags0)
        distA = au_top_tio2_distance_A(header1, coords, elems1, counts1)
        log.append(f"{fname}    dz_A = {r3(distA)}\n")

    # Write mids: i.<alpha>.vasp
    for coords, alpha in mids:
        fname = f"i.{alpha:.2f}.vasp"
        write_poscar_from9(fname, header1, coords, flags0)
        distA = au_top_tio2_distance_A(header1, coords, elems1, counts1)
        log.append(f"{fname}    dz_A = {r3(distA)}\n")

    # Write afters: egs.<alpha>.vasp
    for coords, alpha in afters:
        fname = f"egs.{alpha:.2f}.vasp"
        write_poscar_from9(fname, header1, coords, flags0)
        distA = au_top_tio2_distance_A(header1, coords, elems1, counts1)
        log.append(f"{fname}    dz_A = {r3(distA)}\n")

    Path("dist.txt").write_text("".join(log))

if __name__ == "__main__":
    # Example producing your sample naming/format:
    main(
        file1="d3.1.0.vasp",
        file2="d3.gs.vasp",
        n_images=19,  # i.0.25, i.0.50, i.0.75
        n_before=1,  # ei.0.50
        n_after=1    # egs.0.50
    )
